  1	package hotel.documents;
  2	
  3	import com.fasterxml.jackson.annotation.JsonProperty;
  4	import hotel.reservations.PriceCalculator;
  5	import hotel.reservations.Reservation;
  6	import hotel.rooms.Room;
  7	import hotel.rooms.RoomType;
  8	import java.math.BigDecimal;
  9	import java.time.LocalDate;
 10	
 11	/**
 12	 * The document the guest gets when the reservation is confirmed, at check-out, and on request: the receipt
 13	 * for a guest with a CPF, the invoice for a company's guest, the booking receipt (in English) for a foreigner.
 14	 */
 15	public record ReservationReceipt(
 16	        String title,
 17	        long reservationId,
 18	        String guestName,
 19	        String guestCpf,
 20	        String companyCnpj,
 21	        String companyName,
 22	        String guestPassport,
 23	        String guestCountry,
 24	        int roomNumber,
 25	        RoomType roomType,
 26	        LocalDate checkIn,
 27	        LocalDate checkOut,
 28	        int nights,
 29	        BigDecimal subtotal,
 30	        BigDecimal discount,
 31	        BigDecimal total) {
 32	
 33	    private static final BigDecimal WITHHELD_TAX_RATE = new BigDecimal("0.05");
 34	
 35	    public ReservationReceipt(Reservation reservation, Room room) {
 36	        this(
 37	                titleOf(reservation),
 38	                reservation.id(),
 39	                reservation.guest().name(),
 40	                reservation.guest().cpf(),
 41	                reservation.guest().companyCnpj(),
 42	                reservation.guest().companyName(),
 43	                reservation.guest().passport(),
 44	                reservation.guest().country(),
 45	                room.number(),
 46	                room.type(),
 47	                reservation.checkIn(),
 48	                reservation.checkOut(),
 49	                reservation.price().nights(),
 50	                reservation.price().subtotal(),
 51	                reservation.price().discount(),
 52	                reservation.price().total());
 53	    }
 54	
 55	    private static String titleOf(Reservation reservation) {
 56	        if (reservation.guest().isCompany()) {
 57	            return "Fatura de hospedagem";
 58	        }
 59	        return reservation.guest().isForeigner() ? "Booking receipt" : "Comprovante de reserva";
 60	    }
 61	
 62	    /** The document as it is written in the confirmation e-mail. */
 63	    @JsonProperty("text")
 64	    public String text() {
 65	        if (companyCnpj != null) {
 66	            return invoiceText();
 67	        }
 68	        return guestPassport != null ? bookingReceiptText() : receiptText();
 69	    }
 70	
 71	    private String receiptText() {
 72	        StringBuilder text = new StringBuilder();
 73	        text.append(title).append(" nº ").append(reservationId).append('\n');
 74	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
 75	        appendStayInPortuguese(text);
 76	        return text.toString();
 77	    }
 78	
 79	    private String invoiceText() {
 80	        StringBuilder text = new StringBuilder();
 81	        text.append(title).append(" nº ").append(reservationId).append('\n');
 82	        text.append("Empresa: ").append(companyName).append(" (CNPJ ").append(companyCnpj).append(")\n");
 83	        text.append("Hóspede: ").append(guestName).append('\n');
 84	        appendStayInPortuguese(text);
 85	        BigDecimal withheldTax = PriceCalculator.cents(total.multiply(WITHHELD_TAX_RATE));
 86	        text.append("ISS retido (5%): ").append(TextFormat.money(withheldTax)).append('\n');
 87	        return text.toString();
 88	    }
 89	
 90	    private void appendStayInPortuguese(StringBuilder text) {
 91	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
 92	        text.append("Entrada: ").append(TextFormat.date(checkIn))
 93	                .append(" | Saída: ").append(TextFormat.date(checkOut))
 94	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
 95	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
 96	        if (discount.signum() > 0) {
 97	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
 98	        }
 99	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
100	    }
101	
102	    private String bookingReceiptText() {
103	        StringBuilder text = new StringBuilder();
104	        text.append(title).append(" no. ").append(reservationId).append('\n');
105	        text.append("Guest: ").append(guestName).append(" (passport ").append(guestPassport)
106	                .append(", ").append(guestCountry).append(")\n");
107	        text.append("Room: ").append(roomNumber).append(" (").append(roomType).append(")\n");
108	        text.append("Check-in: ").append(TextFormat.dateInEnglish(checkIn))
109	                .append(" | Check-out: ").append(TextFormat.dateInEnglish(checkOut))
110	                .append(" | ").append(nights).append(nights == 1 ? " night" : " nights").append('\n');
111	        text.append("Nights: ").append(TextFormat.moneyInEnglish(subtotal)).append('\n');
112	        if (discount.signum() > 0) {
113	            text.append("Discount: ").append(TextFormat.moneyInEnglish(discount)).append('\n');
114	        }
115	        text.append("Total: ").append(TextFormat.moneyInEnglish(total)).append('\n');
116	        return text.toString();
117	    }
118	}
119	package hotel.reservations;
120	
121	import hotel.documents.ReservationReceipt;
122	import hotel.messages.EmailSender;
123	import hotel.rooms.Room;
124	import hotel.rooms.Rooms;
125	import java.math.BigDecimal;
126	
127	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
128	public final class ReservationService {
129	
130	    static final String HOTEL_NAME = "Pousada Maré Alta";
131	
132	    private final Rooms rooms;
133	    private final ReservationStore store;
134	    private final PriceCalculator priceCalculator;
135	    private final EmailSender emailSender;
136	
137	    public ReservationService(
138	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
139	        this.rooms = rooms;
140	        this.store = store;
141	        this.priceCalculator = priceCalculator;
142	        this.emailSender = emailSender;
143	    }
144	
145	    public synchronized Reservation create(NewReservation request) {
146	        if (!request.checkOut().isAfter(request.checkIn())) {
147	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
148	        }
149	        if (request.guests() < 1) {
150	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
151	        }
152	        Room room = rooms.find(request.roomNumber())
153	                .orElseThrow(() -> new HotelException(
154	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
155	        if (request.guests() > room.capacity()) {
156	            throw new HotelException(
157	                    ErrorCode.CAPACITY_EXCEEDED,
158	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
159	        }
160	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
161	            throw new HotelException(
162	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
163	        }
164	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
165	        return store.add(request, price);
166	    }
167	
168	    public Reservation find(long reservationId) {
169	        return store.find(reservationId)
170	                .orElseThrow(() -> new HotelException(
171	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
172	    }
173	
174	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
175	    public synchronized Reservation confirm(long reservationId) {
176	        Reservation reservation = find(reservationId);
177	        if (reservation.status() != ReservationStatus.PENDING) {
178	            throw notAllowed(reservation, "confirm");
179	        }
180	        reservation.confirmPayment();
181	        store.update(reservation);
182	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
183	        emailSender.send(
184	                reservation.guest().email(),
185	                "Reserva confirmada - " + HOTEL_NAME,
186	                confirmationEmailBody(reservation, receipt));
187	        return reservation;
188	    }
189	
190	    /**
191	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
192	     * reservation was never paid, so nothing comes back).
193	     */
194	    public synchronized Reservation cancel(long reservationId) {
195	        Reservation reservation = find(reservationId);
196	        if (reservation.status() != ReservationStatus.PENDING
197	                && reservation.status() != ReservationStatus.CONFIRMED) {
198	            throw notAllowed(reservation, "cancel");
199	        }
200	        BigDecimal refund = switch (reservation.ratePlan()) {
201	            case STANDARD -> reservation.amountPaid();
202	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
203	        };
204	        reservation.cancel(refund);
205	        store.update(reservation);
206	        return reservation;
207	    }
208	
209	    public synchronized Reservation checkIn(long reservationId) {
210	        Reservation reservation = find(reservationId);
211	        if (reservation.status() != ReservationStatus.CONFIRMED) {
212	            throw notAllowed(reservation, "check in");
213	        }
214	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
215	        store.update(reservation);
216	        return reservation;
217	    }
218	
219	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
220	    public synchronized ReservationReceipt checkOut(long reservationId) {
221	        Reservation reservation = find(reservationId);
222	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
223	            throw notAllowed(reservation, "check out");
224	        }
225	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
226	        store.update(reservation);
227	        return new ReservationReceipt(reservation, roomOf(reservation));
228	    }
229	
230	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
231	    public ReservationReceipt receiptCopy(long reservationId) {
232	        Reservation reservation = find(reservationId);
233	        if (!reservation.isPaid()) {
234	            throw notAllowed(reservation, "issue a receipt for");
235	        }
236	        return new ReservationReceipt(reservation, roomOf(reservation));
237	    }
238	
239	    private Room roomOf(Reservation reservation) {
240	        return rooms.find(reservation.roomNumber()).orElseThrow();
241	    }
242	
243	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
244	        return "Olá, " + reservation.guest().name() + "!\n\n"
245	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
246	                + receipt.text() + "\n"
247	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
248	                + "Até breve!\n";
249	    }
250	
251	    private static HotelException notAllowed(Reservation reservation, String operation) {
252	        return new HotelException(
253	                ErrorCode.OPERATION_NOT_ALLOWED,
254	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
255	    }
256	}
